struct Idle {}; struct Loading {}; struct Ready { int retries = 0; };
using State = std::variant<Idle, Loading, Ready>;

State next(const State &s, Event e) {
    return std::visit(overloaded{
        [](Idle)          -> State { return Loading{}; },
        [](Loading)       -> State { return Ready{}; },
        [](const Ready &r) -> State { return r; } }, s);
}
